scwin.onpageunload = function() {};
scwin.t1 = function(info) {
    var newInfo = WebSquare.extend({}, info);
    if (info.rowIndex === 0) {
        newInfo.inputType = "checkbox";
    } else {
        newInfo.inputType = "text";
    }
    return newInfo;
}
